// DewfordTown_House2 (zone 31): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0038_room_DewfordTown_House2.txt
// Story (chapter Ch2, Sapphire data/maps/DewfordTown_House2/scripts.inc): script 3, text lines 2-4 after the
// "// ---- story" line.
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry Script_1
    ScriptEntry Script_2
    ScriptEntry DH2_Man             // 3: DewfordTown_House2_EventScript_Man (Silk Scarf; uid 1, data/story/ch2.json)
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    ParentActorMsg MSGFILE_SCRIPT, 0, 0, 0
    LastKeyWait
    ActorMsgClose
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt

Script_2:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 1, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
    .balign 4, 0
// ---- story

DH2_Man:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RECEIVED_SILK_SCARF, L_DH2_ExplainSilkScarf
    h_msgbox 2                      // Gorge your eyes on this! It's a Silk Scarf. ...
    h_closemessage                  // (Black 2: the item script opens its own window)
    h_giveitem ITEM_SILK_SCARF
    h_goto_if_eq HLIB_RESULT, 0, L_DH2_NoRoomForScarf
    h_setflag FLAG_RECEIVED_SILK_SCARF
    h_release
L_DH2_NoRoomForScarf:
    h_msgbox 3                      // Oh, you don't have room? ...
    h_release
L_DH2_ExplainSilkScarf:
    h_msgbox 4                      // The Silk Scarf raises the power of Normal-type moves. ...
    h_release
    .balign 4, 0
